prompt_template:
This project is for IBIS mapping of conversations. The file IBISMap.jsx is a React application running locally at localhost:5176 (or whatever port Vite assigns). When we map a conversation, produce the result as a JSON object in this format:
json{
  "nodes": [
    { "id": "unique-id", "type": "issue|position|supports|objects|unargued", "x": 0, "y": 0, "text": "node text" }
  ],
  "edges": [
    { "id": "unique-id", "from": "node-id", "to": "node-id", "type": "responds-to|supports|objects-to|questions|suggests" }
  ]
}
If a .json map file is attached, load it as the starting state. Apply post-hoc mapping: complete the conversation first, then map it. One thread at a time.

docs.content:
import { useState, useRef, useCallback, useEffect } from "react";

const NODE_TYPES = {
  issue: { label: "Issue", color: "#2563eb", bg: "#dbeafe", border: "#93c5fd" },
  position: { label: "Position", color: "#b45309", bg: "#fef3c7", border: "#fcd34d" },
  supports: { label: "Supports", color: "#065f46", bg: "#d1fae5", border: "#6ee7b7" },
  objects: { label: "Objects to", color: "#991b1b", bg: "#fee2e2", border: "#fca5a5" },
  unargued: { label: "Unargued", color: "#374151", bg: "#f3f4f6", border: "#d1d5db" },
};

const EDGE_TYPES = {
  "responds-to": { label: "responds to", color: "#6b7280" },
  "supports": { label: "supports", color: "#059669" },
  "objects-to": { label: "objects to", color: "#dc2626" },
  "questions": { label: "questions", color: "#2563eb" },
  "suggests": { label: "suggests", color: "#7c3aed" },
};

const INITIAL_NODES = [
  { id: "issue-1", type: "issue", x: 270, y: 40, text: "How might IBIS map our exchanges?" },
  { id: "pos-1", type: "position", x: 60, y: 190, text: "Map post-hoc, one thread at a time" },
  { id: "pos-2", type: "position", x: 490, y: 190, text: "Track design rationale across sessions" },
  { id: "sup-1", type: "supports", x: 20, y: 340, text: "Live classification breaks thinking flow" },
  { id: "sup-2", type: "supports", x: 250, y: 340, text: "Post-hoc still captures reasoning structure" },
  { id: "obj-1", type: "objects", x: 50, y: 460, text: "Loses genuine uncertainty — only survivors visible" },
  { id: "sup-3", type: "supports", x: 490, y: 340, text: "Cumulative value across multiple sessions" },
  { id: "obj-2", type: "objects", x: 480, y: 460, text: "Single ontology assumed — frameworks shift node type" },
  { id: "una-1", type: "unargued", x: 50, y: 580, text: "Is IBIS even the right formalism?" },
  { id: "una-2", type: "unargued", x: 430, y: 580, text: "Claude over-generates positions" },
];

const INITIAL_EDGES = [
  { id: "e1", from: "issue-1", to: "pos-1", type: "responds-to" },
  { id: "e2", from: "issue-1", to: "pos-2", type: "responds-to" },
  { id: "e3", from: "pos-1", to: "sup-1", type: "supports" },
  { id: "e4", from: "pos-1", to: "sup-2", type: "supports" },
  { id: "e5", from: "pos-1", to: "obj-1", type: "objects-to" },
  { id: "e6", from: "pos-2", to: "sup-3", type: "supports" },
  { id: "e7", from: "pos-2", to: "obj-2", type: "objects-to" },
];

const NODE_W = 200;
const NODE_H = 60;

function getNodeCenter(node) {
  return { x: node.x + NODE_W / 2, y: node.y + NODE_H / 2 };
}

// Returns the point where a ray from center in direction (dx,dy) exits the node rect
function rectEdgePoint(node, dx, dy) {
  const cx = node.x + NODE_W / 2;
  const cy = node.y + NODE_H / 2;
  const hw = NODE_W / 2;
  const hh = NODE_H / 2;
  if (dx === 0 && dy === 0) return { x: cx, y: cy };
  const absDx = Math.abs(dx);
  const absDy = Math.abs(dy);
  let t;
  if (absDx * hh > absDy * hw) {
    t = hw / absDx;
  } else {
    t = hh / absDy;
  }
  return { x: cx + dx * t, y: cy + dy * t };
}

function EdgeLine({ edge, nodes, selected, onClick }) {
  const from = nodes.find(n => n.id === edge.from);
  const to = nodes.find(n => n.id === edge.to);
  if (!from || !to) return null;
  const fc = getNodeCenter(from);
  const tc = getNodeCenter(to);
  const mx = (fc.x + tc.x) / 2;
  const my = (fc.y + tc.y) / 2;
  const et = EDGE_TYPES[edge.type] || EDGE_TYPES["responds-to"];
  const dx = tc.x - fc.x;
  const dy = tc.y - fc.y;
  const len = Math.sqrt(dx * dx + dy * dy);
  if (len === 0) return null;
  const ux = dx / len;
  const uy = dy / len;
  const p1 = rectEdgePoint(from, ux, uy);
  const p2 = rectEdgePoint(to, -ux, -uy);
  // pull arrowhead back 2px so it sits on the border cleanly
  const x1 = p1.x;
  const y1 = p1.y;
  const x2 = p2.x - ux * 2;
  const y2 = p2.y - uy * 2;

  return (
    <g onClick={onClick} style={{ cursor: "pointer" }}>
      <line
        x1={x1} y1={y1} x2={x2} y2={y2}
        stroke={selected ? "#f59e0b" : et.color}
        strokeWidth={selected ? 2.5 : 1.5}
        strokeDasharray={edge.type === "objects-to" ? "5,3" : undefined}
        markerEnd={`url(#arrow-${edge.type})`}
        opacity={selected ? 1 : 0.7}
      />
      <line x1={x1} y1={y1} x2={x2} y2={y2} stroke="transparent" strokeWidth={12} />
      <text
        x={mx} y={my - 5}
        textAnchor="middle"
        fontSize={10}
        fill={selected ? "#f59e0b" : et.color}
        fontFamily="'IBM Plex Mono', monospace"
        opacity={0.85}
        style={{ pointerEvents: "none", userSelect: "none" }}
      >
        {et.label}
      </text>
    </g>
  );
}

function NodeBox({ node, selected, onMouseDown, onDoubleClick }) {
  const nt = NODE_TYPES[node.type] || NODE_TYPES.issue;
  return (
    <g
      transform={`translate(${node.x},${node.y})`}
      onMouseDown={onMouseDown}
      onDoubleClick={onDoubleClick}
      style={{ cursor: "grab" }}
    >
      <rect
        width={NODE_W} height={NODE_H} rx={8}
        fill={nt.bg}
        stroke={selected ? "#f59e0b" : nt.border}
        strokeWidth={selected ? 2.5 : 1.5}
        filter={selected ? "url(#sel-shadow)" : undefined}
      />
      <text
        x={NODE_W / 2} y={16}
        textAnchor="middle"
        fontSize={9}
        fontWeight={600}
        letterSpacing={1}
        textTransform="uppercase"
        fill={nt.color}
        fontFamily="'IBM Plex Mono', monospace"
        style={{ pointerEvents: "none", userSelect: "none", textTransform: "uppercase" }}
      >
        {nt.label}
      </text>
      <foreignObject x={8} y={22} width={NODE_W - 16} height={NODE_H - 28}>
        <div xmlns="http://www.w3.org/1999/xhtml" style={{
          fontSize: 11,
          fontFamily: "'Crimson Pro', Georgia, serif",
          color: "#1e293b",
          lineHeight: 1.3,
          overflow: "hidden",
          display: "-webkit-box",
          WebkitLineClamp: 2,
          WebkitBoxOrient: "vertical",
        }}>
          {node.text}
        </div>
      </foreignObject>
    </g>
  );
}

export default function IBISMap() {
  const [nodes, setNodes] = useState(INITIAL_NODES);
  const [edges, setEdges] = useState(INITIAL_EDGES);
  const [selected, setSelected] = useState(null);
  const [editing, setEditing] = useState(null);
  const [editText, setEditText] = useState("");
  const [editType, setEditType] = useState("");
  const [editEdgeType, setEditEdgeType] = useState("");
  const [dragging, setDragging] = useState(null);
  const [connecting, setConnecting] = useState(null);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [zoom, setZoom] = useState(1);
  const [addMode, setAddMode] = useState(null);
  const [addEdgeMode, setAddEdgeMode] = useState(false);
  const [edgeFrom, setEdgeFrom] = useState(null);
  const [newEdgeType, setNewEdgeType] = useState("responds-to");
  const svgRef = useRef(null);
  const panStart = useRef(null);
  const dragOffset = useRef(null);

  const svgCoords = useCallback((e) => {
    const rect = svgRef.current.getBoundingClientRect();
    return {
      x: (e.clientX - rect.left - pan.x) / zoom,
      y: (e.clientY - rect.top - pan.y) / zoom,
    };
  }, [pan, zoom]);

  const handleNodeMouseDown = useCallback((e, id) => {
    e.stopPropagation();
    if (addEdgeMode) {
      if (!edgeFrom) {
        setEdgeFrom(id);
      } else if (edgeFrom !== id) {
        const newEdge = {
          id: `e${Date.now()}`,
          from: edgeFrom,
          to: id,
          type: newEdgeType,
        };
        setEdges(prev => [...prev, newEdge]);
        setEdgeFrom(null);
        setAddEdgeMode(false);
      }
      return;
    }
    setSelected({ kind: "node", id });
    const node = nodes.find(n => n.id === id);
    const coords = svgCoords(e);
    dragOffset.current = { dx: coords.x - node.x, dy: coords.y - node.y };
    setDragging(id);
  }, [addEdgeMode, edgeFrom, newEdgeType, nodes, svgCoords]);

  const handleMouseMove = useCallback((e) => {
    if (dragging) {
      const coords = svgCoords(e);
      setNodes(prev => prev.map(n =>
        n.id === dragging
          ? { ...n, x: coords.x - dragOffset.current.dx, y: coords.y - dragOffset.current.dy }
          : n
      ));
    } else if (isPanning && panStart.current) {
      const dx = e.clientX - panStart.current.x;
      const dy = e.clientY - panStart.current.y;
      setPan({ x: panStart.current.panX + dx, y: panStart.current.panY + dy });
    }
  }, [dragging, isPanning, svgCoords]);

  const handleMouseUp = useCallback(() => {
    setDragging(null);
    setIsPanning(false);
    panStart.current = null;
  }, []);

  const handleSvgMouseDown = useCallback((e) => {
    if (e.target === svgRef.current || e.target.tagName === "svg") {
      setSelected(null);
      setEdgeFrom(null);
      if (!addMode && !addEdgeMode) {
        setIsPanning(true);
        panStart.current = { x: e.clientX, y: e.clientY, panX: pan.x, panY: pan.y };
      }
      if (addMode) {
        const coords = svgCoords(e);
        const newNode = {
          id: `node-${Date.now()}`,
          type: addMode,
          x: coords.x - NODE_W / 2,
          y: coords.y - NODE_H / 2,
          text: "New " + NODE_TYPES[addMode].label,
        };
        setNodes(prev => [...prev, newNode]);
        setAddMode(null);
      }
    }
  }, [addMode, addEdgeMode, pan, svgCoords]);

  const handleWheel = useCallback((e) => {
    e.preventDefault();
    const rect = svgRef.current.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    if (e.ctrlKey || e.metaKey || Math.abs(e.deltaY) > Math.abs(e.deltaX) * 2) {
      // Zoom: scale factor by delta magnitude for smooth pinch/scroll
      const delta = -e.deltaY * (e.deltaMode === 1 ? 20 : 1);
      const factor = Math.pow(1.001, delta);
      setZoom(z => {
        const newZoom = Math.min(Math.max(z * factor, 0.3), 3);
        setPan(p => ({
          x: mouseX - (mouseX - p.x) * (newZoom / z),
          y: mouseY - (mouseY - p.y) * (newZoom / z),
        }));
        return newZoom;
      });
    } else {
      // Pan: two-finger trackpad scroll
      setPan(p => ({ x: p.x - e.deltaX, y: p.y - e.deltaY }));
    }
  }, []);

  const handleNodeDoubleClick = useCallback((e, node) => {
    e.stopPropagation();
    setEditing(node.id);
    setEditText(node.text);
    setEditType(node.type);
  }, []);

  const handleEdgeClick = useCallback((e, id) => {
    e.stopPropagation();
    const edge = edges.find(ed => ed.id === id);
    setSelected({ kind: "edge", id });
    setEditEdgeType(edge.type);
  }, [edges]);

  const commitEdit = useCallback(() => {
    setNodes(prev => prev.map(n =>
      n.id === editing ? { ...n, text: editText, type: editType } : n
    ));
    setEditing(null);
  }, [editing, editText, editType]);

  const deleteSelected = useCallback(() => {
    if (!selected) return;
    if (selected.kind === "node") {
      setNodes(prev => prev.filter(n => n.id !== selected.id));
      setEdges(prev => prev.filter(e => e.from !== selected.id && e.to !== selected.id));
    } else {
      setEdges(prev => prev.filter(e => e.id !== selected.id));
    }
    setSelected(null);
  }, [selected]);

  const updateEdgeType = useCallback((id, type) => {
    setEdges(prev => prev.map(e => e.id === id ? { ...e, type } : e));
    setEditEdgeType(type);
  }, []);

  useEffect(() => {
    const onKey = (e) => {
      if ((e.key === "Delete" || e.key === "Backspace") && selected && !editing) {
        deleteSelected();
      }
      if (e.key === "Escape") {
        setAddMode(null);
        setAddEdgeMode(false);
        setEdgeFrom(null);
        setEditing(null);
        setSelected(null);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [selected, editing, deleteSelected]);

  const selectedNode = selected?.kind === "node" ? nodes.find(n => n.id === selected.id) : null;
  const selectedEdge = selected?.kind === "edge" ? edges.find(e => e.id === selected.id) : null;

  return (
    <div style={{ width: "100vw", height: "100vh", background: "#f8f7f4", fontFamily: "'IBM Plex Mono', monospace", display: "flex", flexDirection: "column" }}>
      <link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;600&family=Crimson+Pro:wght@400;600&display=swap" rel="stylesheet" />

      {/* Toolbar */}
      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 16px", background: "#1e1e2e", borderBottom: "2px solid #312e5e", flexWrap: "wrap" }}>
        <span style={{ color: "#a78bfa", fontSize: 12, fontWeight: 600, letterSpacing: 2, marginRight: 8 }}>IBIS MAP</span>

        {Object.entries(NODE_TYPES).map(([type, nt]) => (
          <button
            key={type}
            onClick={() => { setAddMode(addMode === type ? null : type); setAddEdgeMode(false); setEdgeFrom(null); }}
            style={{
              padding: "4px 10px", fontSize: 10, borderRadius: 4, cursor: "pointer", letterSpacing: 1, fontFamily: "inherit", fontWeight: 600,
              background: addMode === type ? nt.bg : "transparent",
              border: `1.5px solid ${addMode === type ? nt.color : "#4b4b6b"}`,
              color: addMode === type ? nt.color : "#9b9bbf",
              transition: "all 0.15s",
            }}
          >
            + {nt.label.toUpperCase()}
          </button>
        ))}

        <div style={{ width: 1, height: 20, background: "#4b4b6b", margin: "0 4px" }} />

        <button
          onClick={() => { setAddEdgeMode(!addEdgeMode); setAddMode(null); setEdgeFrom(null); }}
          style={{
            padding: "4px 10px", fontSize: 10, borderRadius: 4, cursor: "pointer", letterSpacing: 1, fontFamily: "inherit", fontWeight: 600,
            background: addEdgeMode ? "#fef3c7" : "transparent",
            border: `1.5px solid ${addEdgeMode ? "#b45309" : "#4b4b6b"}`,
            color: addEdgeMode ? "#b45309" : "#9b9bbf",
          }}
        >
          + EDGE
        </button>

        {addEdgeMode && (
          <select
            value={newEdgeType}
            onChange={e => setNewEdgeType(e.target.value)}
            style={{ fontSize: 10, padding: "4px 6px", background: "#2a2a3e", color: "#e2e8f0", border: "1.5px solid #4b4b6b", borderRadius: 4, fontFamily: "inherit" }}
          >
            {Object.entries(EDGE_TYPES).map(([k, v]) => (
              <option key={k} value={k}>{v.label}</option>
            ))}
          </select>
        )}

        <div style={{ width: 1, height: 20, background: "#4b4b6b", margin: "0 4px" }} />

        {selected && (
          <button
            onClick={deleteSelected}
            style={{
              padding: "4px 10px", fontSize: 10, borderRadius: 4, cursor: "pointer", letterSpacing: 1, fontFamily: "inherit", fontWeight: 600,
              background: "transparent", border: "1.5px solid #ef4444", color: "#ef4444",
            }}
          >
            DELETE
          </button>
        )}

        <div style={{ marginLeft: "auto", color: "#6b6b8f", fontSize: 10 }}>
          {addMode ? `click canvas to place ${NODE_TYPES[addMode].label}` :
           addEdgeMode ? (edgeFrom ? "click target node" : "click source node") :
           "drag nodes · double-click to edit · scroll to zoom · delete key removes"}
        </div>
      </div>

      {/* Canvas */}
      <div style={{ flex: 1, position: "relative", overflow: "hidden" }}>
        <svg
          ref={svgRef}
          width="100%" height="100%"
          onMouseDown={handleSvgMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onWheel={handleWheel}
          style={{ cursor: addMode ? "crosshair" : addEdgeMode ? "cell" : isPanning ? "grabbing" : "default" }}
        >
          <defs>
            <filter id="sel-shadow">
              <feDropShadow dx="0" dy="0" stdDeviation="4" floodColor="#f59e0b" floodOpacity="0.5" />
            </filter>
            {Object.entries(EDGE_TYPES).map(([type, et]) => (
              <marker key={type} id={`arrow-${type}`} viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse">
                <path d="M2 1L8 5L2 9" fill="none" stroke={et.color} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
              </marker>
            ))}
            <pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"
              patternTransform={`translate(${pan.x % 40},${pan.y % 40}) scale(${zoom})`}>
              <path d="M 40 0 L 0 0 0 40" fill="none" stroke="#e2e0db" strokeWidth="0.5" />
            </pattern>
          </defs>

          <rect width="100%" height="100%" fill="url(#grid)" />

          <g transform={`translate(${pan.x},${pan.y}) scale(${zoom})`}>
            {edges.map(edge => (
              <EdgeLine
                key={edge.id}
                edge={edge}
                nodes={nodes}
                selected={selected?.kind === "edge" && selected.id === edge.id}
                onClick={(e) => handleEdgeClick(e, edge.id)}
              />
            ))}
            {edgeFrom && (() => {
              const fn = nodes.find(n => n.id === edgeFrom);
              if (!fn) return null;
              const fc = getNodeCenter(fn);
              return <circle cx={fc.x} cy={fc.y} r={8} fill="none" stroke="#f59e0b" strokeWidth={2} strokeDasharray="4,2" />;
            })()}
            {nodes.map(node => (
              <NodeBox
                key={node.id}
                node={node}
                selected={selected?.kind === "node" && selected.id === node.id}
                onMouseDown={(e) => handleNodeMouseDown(e, node.id)}
                onDoubleClick={(e) => handleNodeDoubleClick(e, node)}
              />
            ))}
          </g>
        </svg>

        {/* Edit panel */}
        {editing && (() => {
          const node = nodes.find(n => n.id === editing);
          if (!node) return null;
          return (
            <div style={{
              position: "absolute", top: 20, right: 20, width: 280, background: "#1e1e2e",
              border: "1.5px solid #312e5e", borderRadius: 8, padding: 16, boxShadow: "0 8px 32px rgba(0,0,0,0.3)"
            }}>
              <div style={{ color: "#a78bfa", fontSize: 10, fontWeight: 600, letterSpacing: 2, marginBottom: 10 }}>EDIT NODE</div>
              <div style={{ marginBottom: 8 }}>
                <div style={{ color: "#9b9bbf", fontSize: 9, marginBottom: 4, letterSpacing: 1 }}>TYPE</div>
                <select
                  value={editType}
                  onChange={e => setEditType(e.target.value)}
                  style={{ width: "100%", padding: "6px 8px", background: "#2a2a3e", color: "#e2e8f0", border: "1px solid #4b4b6b", borderRadius: 4, fontFamily: "inherit", fontSize: 11 }}
                >
                  {Object.entries(NODE_TYPES).map(([k, v]) => (
                    <option key={k} value={k}>{v.label}</option>
                  ))}
                </select>
              </div>
              <div style={{ marginBottom: 12 }}>
                <div style={{ color: "#9b9bbf", fontSize: 9, marginBottom: 4, letterSpacing: 1 }}>TEXT</div>
                <textarea
                  value={editText}
                  onChange={e => setEditText(e.target.value)}
                  rows={3}
                  style={{ width: "100%", padding: "6px 8px", background: "#2a2a3e", color: "#e2e8f0", border: "1px solid #4b4b6b", borderRadius: 4, fontFamily: "'Crimson Pro', serif", fontSize: 13, resize: "vertical", boxSizing: "border-box" }}
                  autoFocus
                  onKeyDown={e => { if (e.key === "Enter" && e.metaKey) commitEdit(); if (e.key === "Escape") setEditing(null); }}
                />
              </div>
              <div style={{ display: "flex", gap: 8 }}>
                <button onClick={commitEdit} style={{ flex: 1, padding: "6px", background: "#7c3aed", color: "#fff", border: "none", borderRadius: 4, cursor: "pointer", fontSize: 10, fontFamily: "inherit", fontWeight: 600, letterSpacing: 1 }}>SAVE</button>
                <button onClick={() => setEditing(null)} style={{ flex: 1, padding: "6px", background: "transparent", color: "#9b9bbf", border: "1px solid #4b4b6b", borderRadius: 4, cursor: "pointer", fontSize: 10, fontFamily: "inherit", letterSpacing: 1 }}>CANCEL</button>
              </div>
            </div>
          );
        })()}

        {/* Edge edit panel */}
        {selectedEdge && !editing && (
          <div style={{
            position: "absolute", top: 20, right: 20, width: 240, background: "#1e1e2e",
            border: "1.5px solid #312e5e", borderRadius: 8, padding: 16, boxShadow: "0 8px 32px rgba(0,0,0,0.3)"
          }}>
            <div style={{ color: "#a78bfa", fontSize: 10, fontWeight: 600, letterSpacing: 2, marginBottom: 10 }}>EDGE</div>
            <div style={{ marginBottom: 12 }}>
              <div style={{ color: "#9b9bbf", fontSize: 9, marginBottom: 4, letterSpacing: 1 }}>RELATION TYPE</div>
              <select
                value={editEdgeType}
                onChange={e => updateEdgeType(selectedEdge.id, e.target.value)}
                style={{ width: "100%", padding: "6px 8px", background: "#2a2a3e", color: "#e2e8f0", border: "1px solid #4b4b6b", borderRadius: 4, fontFamily: "inherit", fontSize: 11 }}
              >
                {Object.entries(EDGE_TYPES).map(([k, v]) => (
                  <option key={k} value={k}>{v.label}</option>
                ))}
              </select>
            </div>
