          </div>
        )}

        {/* Zoom indicator */}
        <div style={{ position: "absolute", bottom: 16, left: 16, color: "#9b9bbf", fontSize: 10, letterSpacing: 1 }}>
          {Math.round(zoom * 100)}%
        </div>
      </div>
    </div>
  );
}

