  // Dynamic OU nodes: each ↔ OUH (undirected)
  const ouOnly = ouNodes.filter(n => n.id.startsWith("OU") && n.id !== "OUH");
  ouOnly.forEach(n => pairs.push(["OUH", n.id, false]));
