// ── Minimal markdown renderer: **bold**, *italic*, \n→<br> ──────────────────
function renderMd(text) {
  if (!text) return null;
  // Split on **...** and *...* tokens, preserving order
  const parts = [];
  let remaining = text;
  const re = /(\*\*(.+?)\*\*|\*(.+?)\*)/g;
  let lastIdx = 0, m;
  while ((m = re.exec(text)) !== null) {
    if (m.index > lastIdx) {
      parts.push({ t: "text", v: text.slice(lastIdx, m.index) });
    }
    if (m[0].startsWith("**")) parts.push({ t: "b", v: m[2] });
    else                        parts.push({ t: "i", v: m[3] });
    lastIdx = m.index + m[0].length;
  }
  if (lastIdx < text.length) parts.push({ t: "text", v: text.slice(lastIdx) });

  // Expand \n into line breaks within each segment
  const expand = (str, key) =>
    str.split("\n").flatMap((s, i) => i === 0 ? [s] : [<br key={key+"-br"+i}/>, s]);

  return parts.map((p, i) => {
    if (p.t === "b") return <strong key={i}>{expand(p.v, i)}</strong>;
    if (p.t === "i") return <em key={i}>{expand(p.v, i)}</em>;
    return <span key={i}>{expand(p.v, i)}</span>;
  });
}

