function bentPath(ax, ay, bx, by, R, forward = true) {
  const dx = bx - ax, dy = by - ay;
  const len = Math.sqrt(dx*dx + dy*dy) || 1;
  const ux = dx/len, uy = dy/len;
  if (forward) {
    const sx = ax,        sy = ay + R;
    const ex = bx - ux*R, ey = by - uy*R;
    const vSpan = Math.abs(by - sy);
    return `M${sx},${sy} C${sx},${sy + vSpan*0.60} ${bx-110},${by} ${ex},${ey}`;
  } else {
    const sx = bx,        sy = by - R;
    const ex = ax - ux*R, ey = ay - uy*R;
    const vSpan = Math.abs(ay - sy);
    return `M${sx},${sy} C${bx+110},${sy - vSpan*0.30} ${ax},${ay + R*1.6} ${ex},${ey}`;
  }
}

function Pair({ from, to, etype, highlight, directed = true,
                stateAB, stateBA, onSelect, selKey, byId }) {
  const a = byId(from), b = byId(to);
  if (!a || !b) return null;

  const dx = b.x - a.x, dy = b.y - a.y;
  const len = Math.sqrt(dx*dx + dy*dy) || 1;
  const ux = dx/len, uy = dy/len;
  const off = 6;
  const nx = -uy*off, ny = ux*off;
  const R = 58;

  const edgeColAB = stateAB && stateAB !== "none"
    ? EDGE_STATES.find(s => s.key === stateAB)?.fill : null;
  const edgeColBA = stateBA && stateBA !== "none"
    ? EDGE_STATES.find(s => s.key === stateBA)?.fill : null;

  const baseCol = etype === "internal" ? "#1a1a1a" : (highlight ? EC[etype].hi : EC[etype].base);
  const colAB = edgeColAB ?? baseCol;
  const colBA = edgeColBA ?? baseCol;
  const sw  = highlight ? 3.5 : etype === "internal" ? 1.8 : 2.2;
  const op  = highlight ? 1.0 : etype === "internal" ? 0.55 : 1.0;

  const keyAB = edgeKey(from, to);
  const keyBA = edgeKey(to, from);
  const selAB = selKey === keyAB;
  const selBA = selKey === keyBA;

  const markerFor = (state) => {
    if (etype === "internal" && (!state || state === "none")) return "url(#ah-internal)";
    if (state === "agree")    return "url(#ah-agree)";
    if (state === "disagree") return "url(#ah-disagree)";
    if (state === "unknown")  return "url(#ah-unknown)";
    if (etype === "env")      return "url(#ah-env)";
    if (etype === "ou")       return "url(#ah-ou)";
    return "url(#ah-internal)";
  };
  const markerAB = markerFor(stateAB);
  const markerBA = markerFor(stateBA);

  const fs  = etype === "internal" ? 9 : 9.5;
  const labAB = `${shortName(from)}→${shortName(to)}`;
  const labBA = `${shortName(to)}→${shortName(from)}`;

  if (!directed) {
    const sx = a.x + ux*R, sy = a.y + uy*R;
    const ex = b.x - ux*R, ey = b.y - uy*R;
    return (
      <g opacity={0.6} pointerEvents="none">
        <line x1={sx} y1={sy} x2={ex} y2={ey} stroke={baseCol} strokeWidth={sw} />
      </g>
    );
  }

  const ax1 = a.x+ux*R+nx, ay1 = a.y+uy*R+ny;
  const bx1 = b.x-ux*R+nx, by1 = b.y-uy*R+ny;
  const ax2 = b.x-ux*R-nx, ay2 = b.y-uy*R-ny;
  const bx2 = a.x+ux*R-nx, by2 = a.y+uy*R-ny;

  const idAB = `ep-${keyAB}`;
  const idBA = `ep-${keyBA}`;

  const lenAB = Math.hypot(bx1-ax1, by1-ay1);
  const lenBA = Math.hypot(bx2-ax2, by2-ay2);
  const labWAB = labAB.length * fs * 0.62;
  const labWBA = labBA.length * fs * 0.62;

  const ltrAB = bx1 >= ax1;
  const pathDAB = ltrAB ? `M${ax1},${ay1} L${bx1},${by1}` : `M${bx1},${by1} L${ax1},${ay1}`;
  const offAB   = ltrAB ? "12" : `${Math.max(0, lenAB - 12 - labWAB)}`;

  const ltrBA = bx2 >= ax2;
  const pathDBA = ltrBA ? `M${ax2},${ay2} L${bx2},${by2}` : `M${bx2},${by2} L${ax2},${ay2}`;
  const offBA   = ltrBA ? "12" : `${Math.max(0, lenBA - 12 - labWBA)}`;

  return (
    <g opacity={op}>
      <defs>
        <path id={idAB} d={pathDAB} />
        <path id={idBA} d={pathDBA} />
      </defs>

      {/* A→B */}
      <g style={{ cursor: "pointer" }}
        onClick={e => { e.stopPropagation(); onSelect({ key: keyAB, a: from, b: to, t: etype }); }}>
        <line x1={ax1} y1={ay1} x2={bx1} y2={by1} stroke="transparent" strokeWidth={14} />
        <line x1={ax1} y1={ay1} x2={bx1} y2={by1}
          stroke={colAB} strokeWidth={selAB ? sw+2 : sw} markerEnd={markerAB} />
        <text fontSize={fs} fontFamily="monospace" fontWeight="700"
          fill={selAB ? "#000" : "#333"}
          stroke="white" strokeWidth={3} paintOrder="stroke">
          <textPath href={`#${idAB}`} startOffset={offAB}>
            <tspan dy="-4">{labAB}</tspan>
          </textPath>
        </text>
      </g>

      {/* B→A */}
      <g style={{ cursor: "pointer" }}
        onClick={e => { e.stopPropagation(); onSelect({ key: keyBA, a: to, b: from, t: etype }); }}>
        <line x1={ax2} y1={ay2} x2={bx2} y2={by2} stroke="transparent" strokeWidth={14} />
        <line x1={ax2} y1={ay2} x2={bx2} y2={by2}
          stroke={colBA} strokeWidth={selBA ? sw+2 : sw} markerEnd={markerBA} />
        <text fontSize={fs} fontFamily="monospace" fontWeight="700"
          fill={selBA ? "#000" : "#333"}
          stroke="white" strokeWidth={3} paintOrder="stroke">
          <textPath href={`#${idBA}`} startOffset={offBA}>
            <tspan dy="-4">{labBA}</tspan>
          </textPath>
        </text>
      </g>
    </g>
  );
}

// ── Auto-wrap label text to fit inside a circle of radius R ─────────────
// Breaks on existing \n first, then wraps long words-based lines to maxChars.
// Returns array of line strings that will fit within the usable chord width.
function wrapLabel(text, maxChars = 11) {
  const segments = text.split("\n");
  const lines = [];
  segments.forEach(seg => {
    const words = seg.split(" ");
    let cur = "";
    words.forEach(w => {
      const candidate = cur ? cur + " " + w : w;
      if (candidate.length <= maxChars) {
        cur = candidate;
      } else {
        if (cur) lines.push(cur);
        // If a single word exceeds maxChars, let it sit alone (will be small font)
        cur = w;
      }
    });
    if (cur) lines.push(cur);
  });
  return lines.length ? lines : [text];
}

function Node({ n, fill, selected, onSelect, labelOverride }) {
  const [hov, setHov] = useState(false);
  const R = 54;
  const rawLabel = labelOverride || n.label;
  const hasId   = typeof n.id === "number";
  const hasTier = !!n.tier;

  // Reserve vertical space for S# and tier badges; tighter budget = fewer chars per line
  const idH   = hasId   ? 12 : 0;
  const tierH = hasTier ? 11 : 0;
  // Available height for label lines inside circle (rough usable chord at mid-radius)
  const maxLines   = hasTier || hasId ? 4 : 5;
  const lines      = wrapLabel(rawLabel, 11).slice(0, maxLines);
  const nLines     = lines.length;

  // Font size: shrink for more lines or longer individual words
  const maxLineLen = Math.max(...lines.map(l => l.length));
  const fs = maxLineLen > 13 ? 8 : maxLineLen > 10 ? 9.5 : nLines > 3 ? 10 : 11.5;
  const lh = fs + 3;

  const labelH = nLines * lh;
  const totalH = idH + labelH + tierH;
  const topY   = -totalH / 2;

  return (
    <g transform={`translate(${n.x},${n.y})`} style={{ cursor: "pointer" }}
      onClick={() => onSelect(n)}
      onMouseEnter={() => setHov(true)}
      onMouseLeave={() => setHov(false)}>
      {(selected || hov) && (
        <circle r={R + 12} fill="none" stroke={n.b}
          strokeWidth={1.5} strokeDasharray="5 3" opacity={0.45} />
      )}
      <circle r={R} fill={fill} stroke={n.b} strokeWidth={selected ? 8 : hov ? 7 : 5} />

      {/* S# identifier at top */}
      {hasId && (
        <text x={0} y={topY + 9}
          fontSize={9} fontWeight="800" fontFamily="monospace"
          textAnchor="middle" fill={n.b} opacity={0.85}>
          S{n.id}
        </text>
      )}

      {/* Label lines centred */}
      {lines.map((ln, i) => (
        <text key={i}
          x={0} y={topY + idH + lh * 0.85 + i * lh}
          fontSize={fs} fontWeight="700"
          fontFamily="system-ui, sans-serif" textAnchor="middle" fill="#111">
          {ln}
        </text>
      ))}

      {/* VSM tier at bottom */}
      {hasTier && (
        <text x={0} y={topY + idH + labelH + tierH - 1}
          fontSize={7.5} fontFamily="monospace" textAnchor="middle" fill="#555">
          {n.tier}
        </text>
      )}
    </g>
  );
}

