// ── Build flat assessment sequence (nodes then all directed edges) ─────────
function buildAssessmentSequence(show, envNodes = [], ouNodes = [], envPairs = [], ouPairs = []) {
  const items = [];
  if (show.int) INTERNAL.forEach(n => items.push({ type: "node", id: n.id }));
  if (show.env) envNodes.forEach(n => items.push({ type: "node", id: n.id }));
  if (show.ou)  ouNodes.forEach(n => items.push({ type: "node", id: n.id }));
  if (show.int) {
    INT_PAIRS.forEach(([a,b]) => {
      items.push({ type: "edge", id: edgeKey(a, b) });
      items.push({ type: "edge", id: edgeKey(b, a) });
    });
  }
  if (show.int && show.env) {
    envPairs.forEach(([a,b]) => {
      items.push({ type: "edge", id: edgeKey(a, b) });
      items.push({ type: "edge", id: edgeKey(b, a) });
    });
  }
  if (show.int && show.ou) {
    ouPairs.filter(([,,dir]) => dir).forEach(([a,b]) => {
      items.push({ type: "edge", id: edgeKey(a, b) });
      items.push({ type: "edge", id: edgeKey(b, a) });
    });
  }
  return items;
}

