// ── DIAGRAM CANVAS (shared between Setup and Survey modes) ────────────────
// ══════════════════════════════════════════════════════════════════════════
function DiagramCanvas({
  show, assess, sel, selEdge, onSelectNode, onSelectEdge, enterpriseName,
  svgRef, labelMap = {},
  envNodes = [], ouNodes = [], envPairs = [], ouPairs = [],
}) {
  const [zoom, setZoom] = useState(0.50);
  const [pan, setPan]   = useState({ x: 30, y: 20 });
  const drag = useRef(false);
  const last = useRef(null);
  const containerRef = useRef(null);

  // Must use non-passive wheel listener so e.preventDefault() works in Chrome/Safari
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const handler = e => {
      e.preventDefault();
      if (e.ctrlKey || e.metaKey) {
        const delta = Math.max(-15, Math.min(15, e.deltaY));
        const factor = 1 - delta * 0.008;
        const rect = el.getBoundingClientRect();
        const mx = e.clientX - rect.left;
        const my = e.clientY - rect.top;
        setZoom(z => {
          const newZ = Math.max(0.15, Math.min(3, z * factor));
          setPan(q => ({
            x: mx - (mx - q.x) * (newZ / z),
            y: my - (my - q.y) * (newZ / z),
          }));
          return newZ;
        });
      } else {
        setPan(q => ({ x: q.x - e.deltaX, y: q.y - e.deltaY }));
      }
    };
    el.addEventListener("wheel", handler, { passive: false });
    return () => el.removeEventListener("wheel", handler);
  }, []);

  const dn = e => {
    if (["circle","text"].includes(e.target.tagName)) return;
    drag.current = true; last.current = { x: e.clientX, y: e.clientY };
  };
  const mv = e => {
    if (!drag.current) return;
    setPan(q => ({ x: q.x + e.clientX - last.current.x, y: q.y + e.clientY - last.current.y }));
    last.current = { x: e.clientX, y: e.clientY };
  };
  const up = () => { drag.current = false; };

  const selId   = sel?.id ?? null;
  const selEKey = selEdge?.key ?? null;

  const byId = makeById(envNodes, ouNodes);
  const zone = { ...ZONES, env: envZone(envNodes.length), ou: ouZone(ouNodes.filter(n=>n.id.startsWith("OU")&&n.id!=="OUH").length) };

  const allEdges = [
    ...INT_PAIRS.map(([a,b])    => ({ a, b, t: "internal", directed: true  })),
    ...envPairs.map(([a,b])     => ({ a, b, t: "env",      directed: true  })),
    ...ouPairs.map(([a,b,dir])  => ({ a, b, t: "ou",       directed: dir   })),
  ];
  const isHL    = (a, b) => selId != null && (a===selId || b===selId);
  const getFill = id => STATES.find(s => s.key === (assess[id] || "none"))?.fill ?? "#fff";

  return (
    <div ref={containerRef} style={{ flex: 1, position: "relative", overflow: "hidden", background: "#fff" }}
      onMouseDown={dn} onMouseMove={mv} onMouseUp={up} onMouseLeave={up}>
      <svg ref={svgRef} width="100%" height="100%"
        style={{ display: "block", cursor: "grab", overflow: "hidden" }}>
        <defs>
          {[
            { id: "ah-internal",  fill: "#1a1a1a"   },
            { id: "ah-env",       fill: EC.env.base  },
            { id: "ah-ou",        fill: EC.ou.base   },
            { id: "ah-agree",     fill: "#a4dd00"    },
            { id: "ah-disagree",  fill: "#f44e3b"    },
            { id: "ah-unknown",   fill: "#73d8ff"    },
          ].map(({ id, fill }) => (
            <marker key={id} id={id}
              markerWidth="5" markerHeight="5" refX="4.5" refY="2.5" orient="auto">
              <path d="M0,0 L5,2.5 L0,5 z" fill={fill} />
            </marker>
          ))}
        </defs>

        <g transform={`translate(${pan.x},${pan.y}) scale(${zoom})`}>

          {/* Zone backgrounds */}
          {show.int && (
            <rect x={zone.int.x} y={zone.int.y}
              width={zone.int.w} height={zone.int.h}
              fill={BG.internal.fill} stroke={BG.internal.stroke}
              strokeWidth={1.5} rx={14} />
          )}
          {show.env && (
            <rect x={zone.env.x} y={zone.env.y}
              width={zone.env.w} height={zone.env.h}
              fill={BG.env.fill} stroke={BG.env.stroke}
              strokeWidth={1.5} rx={14} />
          )}
          {show.ou && (
            <rect x={zone.ou.x} y={zone.ou.y}
              width={zone.ou.w} height={zone.ou.h}
              fill={BG.ou.fill} stroke={BG.ou.stroke}
              strokeWidth={1.5} rx={14} />
          )}
          {/* OU ENV sub-zone — Suppliers/Customers of the Operating Units */}
          {show.ou && (
            <rect x={OU_ENV_ZONE.x} y={OU_ENV_ZONE.y}
              width={OU_ENV_ZONE.w} height={OU_ENV_ZONE.h}
              fill={BG.env.fill} stroke={BG.env.stroke}
              strokeWidth={1.5} rx={10} />
          )}

          {/* Zone labels */}
          {show.int && (
            <text x={zone.int.x + 14} y={zone.int.y + 22}
              fontSize={13} fill={C.vsm3} fontFamily="monospace"
              fontWeight="700" letterSpacing={2} opacity={0.9}>INTERNAL</text>
          )}
          {show.env && (
            <text x={zone.env.x + 10} y={zone.env.y + 22}
              fontSize={13} fill={C.env} fontFamily="monospace"
              fontWeight="700" letterSpacing={2} opacity={0.9}>ENV</text>
          )}
          {show.ou && (
            <text x={zone.ou.x + 14} y={zone.ou.y + 22}
              fontSize={13} fill={C.vsm1} fontFamily="monospace"
              fontWeight="700" letterSpacing={2} opacity={0.9}>VSM-1 · OPERATING UNITS</text>
          )}
          {show.ou && (
            <text x={OU_ENV_ZONE.x + 10} y={OU_ENV_ZONE.y + 18}
              fontSize={10} fill={C.env} fontFamily="monospace"
              fontWeight="700" letterSpacing={1} opacity={0.9}>OU ENV</text>
          )}

          {/* Edges */}
          {show.int && INT_PAIRS.map(([a,b], i) => (
            <Pair key={`i${i}`} from={a} to={b} etype="internal" highlight={isHL(a,b)}
              directed={true} byId={byId}
              stateAB={assess[edgeKey(a,b)]} stateBA={assess[edgeKey(b,a)]}
              selKey={selEKey} onSelect={onSelectEdge} />
          ))}
          {show.int && show.env && envPairs.map(([a,b], i) => (
            <Pair key={`e${i}`} from={a} to={b} etype="env" highlight={isHL(a,b)}
              directed={true} byId={byId}
              stateAB={assess[edgeKey(a,b)]} stateBA={assess[edgeKey(b,a)]}
              selKey={selEKey} onSelect={onSelectEdge} />
          ))}
          {show.int && show.ou && ouPairs.map(([a,b,dir], i) => (
            <Pair key={`o${i}`} from={a} to={b} etype="ou" highlight={isHL(a,b)}
              directed={dir} byId={byId}
              stateAB={assess[edgeKey(a,b)]} stateBA={assess[edgeKey(b,a)]}
              selKey={selEKey} onSelect={onSelectEdge} />
          ))}

          {/* Nodes */}
          {show.int && INTERNAL.map(n => (
            <Node key={n.id} n={n} fill={getFill(n.id)}
              selected={selId===n.id} onSelect={onSelectNode}
              labelOverride={labelMap[n.id]} />
          ))}
          {show.env && envNodes.map(n => (
            <Node key={n.id} n={n} fill={getFill(n.id)}
              selected={selId===n.id} onSelect={onSelectNode}
              labelOverride={labelMap[n.id]} />
          ))}
          {show.ou && ouNodes.map(n => (
            <Node key={n.id} n={n} fill={getFill(n.id)}
              selected={selId===n.id} onSelect={onSelectNode}
              labelOverride={labelMap[n.id]} />
          ))}

          {/* Enterprise name banner */}
          <g transform={`translate(${zone.int.x + zone.int.w / 2}, ${zone.int.y - 44})`}>
            <rect x={-280} y={-22} width={560} height={38}
              fill="#f9fafb" stroke="#e5e7eb" rx={6} />
            <text x={0} y={8} fontSize={20} textAnchor="middle"
              fill={enterpriseName ? "#1a1a18" : "#9ca3af"}
              fontFamily="system-ui, sans-serif" fontWeight="700">
              {enterpriseName || "Enterprise Name"}
            </text>
          </g>
        </g>
      </svg>

      {/* Reset zoom button */}
      <button
        onClick={() => { setZoom(0.50); setPan({ x: 30, y: 20 }); }}
        style={{
          position: "absolute", bottom: 32, left: 12,
          padding: "3px 8px", fontSize: 10, cursor: "pointer",
          background: "#f9fafb", color: "#9ca3af",
          border: "1px solid #e5e7eb", borderRadius: 3,
        }}>⌂ Reset</button>
      <div style={{
        position: "absolute", bottom: 10, left: 12,
        fontSize: 9.5, color: "#d1d5db", fontFamily: "monospace",
      }}>
        {Math.round(zoom * 100)}% · two-finger swipe=pan · pinch=zoom · click-drag=pan
      </div>
    </div>
  );
}

