        </div>
        <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
          letterSpacing: 1, marginBottom: 4 }}>EVIDENCE</div>
        <textarea
          value={(notes[sel.id] || {}).evidence || ""}
          onChange={e => setNote(sel.id, "evidence", e.target.value)}
          placeholder="What evidence supports this assessment? (**bold**, *italic*)"
          style={{ width: "100%", height: 70, fontSize: 10.5, padding: "5px 7px",
            border: "1px solid #e5e7eb", borderRadius: 4, resize: "vertical",
            fontFamily: "system-ui, sans-serif", marginBottom: 2, boxSizing: "border-box" }}
        />
        <div style={{ fontSize: 8, color: "#d1d5db", fontFamily: "monospace",
          marginBottom: 8 }}>**bold** · *italic*</div>
        <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
          letterSpacing: 1, marginBottom: 4 }}>SUGGESTIONS</div>
        <textarea
          value={(notes[sel.id] || {}).suggestions || ""}
          onChange={e => setNote(sel.id, "suggestions", e.target.value)}
          placeholder="What would make this better? (**bold**, *italic*)"
          style={{ width: "100%", height: 70, fontSize: 10.5, padding: "5px 7px",
            border: "1px solid #e5e7eb", borderRadius: 4, resize: "vertical",
            fontFamily: "system-ui, sans-serif", marginBottom: 2, boxSizing: "border-box" }}
        />
        <div style={{ fontSize: 8, color: "#d1d5db", fontFamily: "monospace",
          marginBottom: 10 }}>**bold** · *italic*</div>
        <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
          letterSpacing: 1, marginBottom: 6 }}>
          CONNECTIONS ({selEdges.length})
        </div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 3 }}>
          {selEdges.map(({ a, b, t }, i) => {
            const oid = a === selId ? b : a;
            const other = byId(oid);
            if (!other) return null;
            return (
              <span key={i} onClick={() => onSelectNode(other)} style={{
                display: "inline-flex", alignItems: "center", gap: 3,
                padding: "2px 6px", borderRadius: 3, fontSize: 9.5,
                background: "#f9fafb", border: `1px solid ${other.b}55`,
                cursor: "pointer", color: "#374151",
              }}>
                <span style={{ width: 5, height: 5, borderRadius: "50%",
                  background: other.b, display: "inline-block", flexShrink: 0 }} />
                {getLabel(other).replace("\n", " ")}
              </span>
            );
          })}
        </div>
      </>
    );
  }

  if (selEdge) {
    const descVal = descMap[selEKey] || "";
    const nodeA = byId(selEdge.a);
    const nodeB = byId(selEdge.b);
    return (
      <>
        <div style={{ fontSize: 12, fontWeight: 800, color: "#374151", marginBottom: 2 }}>
          {shortName(selEdge.a, [], [])} → {shortName(selEdge.b, [], [])}
        </div>
        <div style={{ fontSize: 10, color: "#6b7280", marginBottom: 10 }}>
          {nodeA ? getLabel(nodeA).replace("\n"," ") : selEdge.a} → {nodeB ? getLabel(nodeB).replace("\n"," ") : selEdge.b}
        </div>

        {/* Description */}
        <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
          letterSpacing: 1, marginBottom: 4 }}>DESCRIPTION
          {setupMode && <span style={{ fontSize: 8, color: "#d1d5db", marginLeft: 6 }}>shown to respondents</span>}
        </div>
        {setupMode ? (
          <>
            <textarea
              value={descVal}
              onChange={e => setDesc && setDesc(selEKey, e.target.value)}
              placeholder="Explain what this relationship means for respondents… (**bold**, *italic*)"
              style={{ width: "100%", height: 72, fontSize: 10.5, padding: "5px 7px",
                border: "1px solid #e5e7eb", borderRadius: 4, resize: "vertical",
                fontFamily: "system-ui, sans-serif", marginBottom: 2, boxSizing: "border-box" }}
            />
            <div style={{ fontSize: 8, color: "#d1d5db", fontFamily: "monospace",
              marginBottom: 10 }}>**bold** · *italic* · line break with Enter</div>
          </>
        ) : descVal ? (
          <div style={{ fontSize: 10.5, color: "#374151", lineHeight: 1.6,
            marginBottom: 10, padding: "6px 8px", background: "#f9fafb",
            border: "1px solid #f3f4f6", borderRadius: 4 }}>
            {renderMd(descVal)}
          </div>
        ) : null}
        <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
          letterSpacing: 1, marginBottom: 5 }}>ASSESSMENT</div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 3, marginBottom: 10 }}>
          {EDGE_STATES.map(s => {
            const active = (assess[selEKey] || "none") === s.key;
            return (
              <button key={s.key}
                onClick={() => setAssess(a => ({ ...a, [selEKey]: s.key }))}
                style={{
                  padding: "2px 7px", borderRadius: 3, fontSize: 9.5, cursor: "pointer",
                  background: active ? s.fill : "#f9fafb",
                  color:      active ? "#111" : "#6b7280",
                  border:     `1.5px solid ${active ? s.fill : "#e5e7eb"}`,
                  fontWeight: active ? 700 : 400,
                }}>{s.label}</button>
            );
          })}
        </div>
        <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
          letterSpacing: 1, marginBottom: 4 }}>EVIDENCE</div>
        <textarea
          value={(notes[selEKey] || {}).evidence || ""}
          onChange={e => setNote(selEKey, "evidence", e.target.value)}
          placeholder="What evidence supports this assessment? (**bold**, *italic*)"
          style={{ width: "100%", height: 75, fontSize: 10.5, padding: "5px 7px",
            border: "1px solid #e5e7eb", borderRadius: 4, resize: "vertical",
            fontFamily: "system-ui, sans-serif", marginBottom: 2, boxSizing: "border-box" }}
        />
        <div style={{ fontSize: 8, color: "#d1d5db", fontFamily: "monospace",
          marginBottom: 8 }}>**bold** · *italic*</div>
        <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
          letterSpacing: 1, marginBottom: 4 }}>SUGGESTIONS</div>
        <textarea
          value={(notes[selEKey] || {}).suggestions || ""}
          onChange={e => setNote(selEKey, "suggestions", e.target.value)}
          placeholder="What would make this better? (**bold**, *italic*)"
          style={{ width: "100%", height: 75, fontSize: 10.5, padding: "5px 7px",
            border: "1px solid #e5e7eb", borderRadius: 4, resize: "vertical",
            fontFamily: "system-ui, sans-serif", marginBottom: 2, boxSizing: "border-box" }}
        />
        <div style={{ fontSize: 8, color: "#d1d5db", fontFamily: "monospace",
          marginBottom: 6 }}>**bold** · *italic*</div>
        <div style={{ display: "flex", gap: 6, marginTop: 4 }}>
          <button onClick={() => onSelectNode(byId(selEdge.a))} style={{
            flex: 1, padding: "3px 0", fontSize: 9.5, cursor: "pointer",
            background: "#f9fafb", border: "1px solid #e5e7eb", borderRadius: 3,
            color: "#374151",
          }}>→ {nodeA ? getLabel(nodeA).replace("\n"," ") : selEdge.a}</button>
          <button onClick={() => onSelectNode(byId(selEdge.b))} style={{
            flex: 1, padding: "3px 0", fontSize: 9.5, cursor: "pointer",
            background: "#f9fafb", border: "1px solid #e5e7eb", borderRadius: 3,
            color: "#374151",
          }}>→ {nodeB ? getLabel(nodeB).replace("\n"," ") : selEdge.b}</button>
        </div>
      </>
    );
  }

  return (
    <div style={{ fontSize: 11, color: "#9ca3af", lineHeight: 1.7 }}>
      Click any node or edge to assess it.<br />
      Nodes: urgency status + evidence + suggestions.<br />
      Edges: working/broken + evidence + suggestions.
    </div>
  );
}

// ── Shared form helpers (must be module-level to avoid focus loss on re-render)
function Btn({ children, onClick, accent }) {
  return (
    <button onClick={onClick} style={{
      padding: "4px 10px", borderRadius: 3, fontSize: 11, cursor: "pointer",
      background: accent ? "#2a5c3f" : "#f9fafb",
      color: accent ? "#fff" : "#374151",
      border: `1px solid ${accent ? "#2a5c3f" : "#e5e7eb"}`,
      fontWeight: accent ? 600 : 400,
    }}>{children}</button>
  );
}

function FieldLabel({ children }) {
  return (
    <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
      letterSpacing: 1.2, textTransform: "uppercase", marginBottom: 5 }}>
      {children}
    </div>
  );
}

function Field({ label, children, style }) {
  return (
    <div style={{ marginBottom: 14, ...style }}>
      <FieldLabel>{label}</FieldLabel>
      {children}
    </div>
  );
}

const inputStyle = {
  width: "100%", fontSize: 11, padding: "5px 8px",
  border: "1px solid #e5e7eb", borderRadius: 3,
  fontFamily: "system-ui, sans-serif", boxSizing: "border-box",
  background: "#fafafa", color: "#111",
};
const taStyle = { ...inputStyle, resize: "vertical", lineHeight: 1.5 };

// ══════════════════════════════════════════════════════════════════════════
// ── SETUP MODE ────────────────────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════════════
function SetupMode({
  config, setConfig, assess, setAssess, notes, setNote, show, setShow,
  svgRef, onSaveJSON, onLoadJSON, onExportSVG, onPrint, fileRef,
  setNodeLabel, setDesc,
  envNodes, ouNodes, envPairs, ouPairs, setEnvConn,
}) {
  const [sel, setSel]       = useState(null);
  const [selEdge, setSelEdge] = useState(null);
  const [worldInput, setWorldInput] = useState("");
  const [dragSrc, setDragSrc] = useState(null);

  const handleSelectNode = node => { setSelEdge(null); setSel(node); };
  const handleSelectEdge = edge => { setSel(null); setSelEdge(edge); };

  const addWorld = () => {
    const v = worldInput.trim();
    if (!v || config.worlds.includes(v)) return;
    setConfig(c => ({ ...c, worlds: [...c.worlds, v] }));
    setWorldInput("");
  };
  const removeWorld = w => setConfig(c => ({ ...c, worlds: c.worlds.filter(x => x !== w) }));
  const editWorld  = (i, val) => setConfig(c => {
    const updated = [...c.worlds]; updated[i] = val; return { ...c, worlds: updated };
  });
  const moveWorld  = (i, dir) => setConfig(c => {
    const updated = [...c.worlds];
    const j = i + dir;
    if (j < 0 || j >= updated.length) return c;
    [updated[i], updated[j]] = [updated[j], updated[i]];
    return { ...c, worlds: updated };
  });

  const handleDragStart = (e, idx) => {
    setDragSrc(idx);
    e.dataTransfer.effectAllowed = "move";
  };
  const handleDrop = (e, idx) => {
    e.preventDefault();
    if (dragSrc === null || dragSrc === idx) return;
    const newWorlds = [...config.worlds];
    const [moved] = newWorlds.splice(dragSrc, 1);
    newWorlds.splice(idx, 0, moved);
    setConfig(c => ({ ...c, worlds: newWorlds }));
    setDragSrc(null);
  };



  return (
    <div style={{ flex: 1, display: "flex", overflow: "hidden" }}>

      {/* ── Left panel: Survey identity + Worlds ── */}
      <div style={{
        width: 270, background: "#f9fafb", borderRight: "1.5px solid #e5e7eb",
        overflowY: "auto", padding: "14px 14px",
        display: "flex", flexDirection: "column", gap: 0,
      }}>

        <div style={{ marginBottom: 18 }}>
          <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
            letterSpacing: 1.5, marginBottom: 10, paddingBottom: 5,
            borderBottom: "1px solid #f3f4f6" }}>SURVEY IDENTITY
            <span style={{ fontSize: 8, fontWeight: 400, color: "#d1d5db", marginLeft: 6 }}>
              shown read-only in survey
            </span>
          </div>

          <Field label="Enterprise / Organization">
            <input
              value={config.enterprise}
              onChange={e => setConfig(c => ({ ...c, enterprise: e.target.value }))}
              placeholder="Organization name…"
              style={inputStyle}
            />
          </Field>

          <Field label="Focal Point / Description">
            <textarea
              value={config.focalPoint}
              onChange={e => setConfig(c => ({ ...c, focalPoint: e.target.value }))}
              placeholder="Statement of purpose or focus being assessed…"
              rows={3}
              style={{ ...taStyle, minHeight: 56 }}
            />
          </Field>

          <Field label="Preview / Instructions">
            <textarea
              value={config.previewText}
              onChange={e => setConfig(c => ({ ...c, previewText: e.target.value }))}
              placeholder="Instructions shown to respondents before they begin…"
              rows={3}
              style={{ ...taStyle, minHeight: 56 }}
            />
          </Field>

          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
            <Field label="Date">
              <input
                value={config.date}
                onChange={e => setConfig(c => ({ ...c, date: e.target.value }))}
                placeholder="MM-DD-YYYY"
                style={inputStyle}
              />
            </Field>
            <Field label="Time Frame">
              <input
                value={config.timeFrame}
                onChange={e => setConfig(c => ({ ...c, timeFrame: e.target.value }))}
                placeholder="e.g. Spring 2026"
                style={inputStyle}
              />
            </Field>
          </div>

          <Field label="Survey ID">
            <input
              value={config.surveyId}
              onChange={e => setConfig(c => ({ ...c, surveyId: e.target.value }))}
              placeholder="Optional unique identifier"
              style={inputStyle}
            />
          </Field>
        </div>

        {/* Node counts + labels editor */}
        <div style={{ marginBottom: 18 }}>
          <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
            letterSpacing: 1.5, marginBottom: 8, paddingTop: 5, paddingBottom: 5,
            borderTop: "1px solid #f3f4f6", borderBottom: "1px solid #f3f4f6" }}>
            NODE LABELS
            <span style={{ fontSize: 8, fontWeight: 400, color: "#d1d5db", marginLeft: 6 }}>
              shown in diagram + survey
            </span>
          </div>

          {/* OU count control */}
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
            <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
              letterSpacing: 1, flex: 1 }}>OPERATING UNITS</div>
            <button onClick={() => setConfig(c => ({ ...c, ouCount: Math.max(1, c.ouCount - 1) }))}
              style={{ width: 22, height: 22, border: "1px solid #e5e7eb", borderRadius: 3,
                background: "#f9fafb", cursor: "pointer", fontSize: 14, lineHeight: 1 }}>−</button>
            <span style={{ fontSize: 11, fontFamily: "monospace", minWidth: 16, textAlign: "center" }}>
              {config.ouCount}
            </span>
            <button onClick={() => setConfig(c => ({ ...c, ouCount: Math.min(10, c.ouCount + 1) }))}
              style={{ width: 22, height: 22, border: "1px solid #e5e7eb", borderRadius: 3,
                background: "#f9fafb", cursor: "pointer", fontSize: 14, lineHeight: 1 }}>+</button>
          </div>
          {ouNodes.filter(n => n.id.startsWith("OU") && n.id !== "OUH").map(n => (
            <div key={n.id} style={{ display: "grid", gridTemplateColumns: "40px 1fr",
              alignItems: "center", gap: 5, marginBottom: 4 }}>
              <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
                textAlign: "right" }}>{n.id}</div>
              <input value={config.nodeLabels[n.id] ?? n.label}
                onChange={e => setNodeLabel(n.id, e.target.value)}
                style={{ ...inputStyle, fontSize: 10, padding: "3px 6px" }} />
            </div>
          ))}

          {/* ENV count control */}
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 10, marginBottom: 8 }}>
            <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
              letterSpacing: 1, flex: 1 }}>ENV ACTORS</div>
            <button onClick={() => setConfig(c => ({ ...c, envCount: Math.max(1, c.envCount - 1) }))}
              style={{ width: 22, height: 22, border: "1px solid #e5e7eb", borderRadius: 3,
                background: "#f9fafb", cursor: "pointer", fontSize: 14, lineHeight: 1 }}>−</button>
            <span style={{ fontSize: 11, fontFamily: "monospace", minWidth: 16, textAlign: "center" }}>
              {config.envCount}
            </span>
            <button onClick={() => setConfig(c => ({ ...c, envCount: Math.min(10, c.envCount + 1) }))}
              style={{ width: 22, height: 22, border: "1px solid #e5e7eb", borderRadius: 3,
                background: "#f9fafb", cursor: "pointer", fontSize: 14, lineHeight: 1 }}>+</button>
          </div>
          {envNodes.map(n => (
            <div key={n.id} style={{ marginBottom: 5 }}>
              <div style={{ display: "grid", gridTemplateColumns: "40px 1fr",
                alignItems: "center", gap: 5, marginBottom: 2 }}>
                <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
                  textAlign: "right" }}>{n.id}</div>
                <input value={config.nodeLabels[n.id] ?? n.label}
                  onChange={e => setNodeLabel(n.id, e.target.value)}
                  style={{ ...inputStyle, fontSize: 10, padding: "3px 6px" }} />
              </div>
              <div style={{ display: "grid", gridTemplateColumns: "40px 1fr",
                alignItems: "center", gap: 5 }}>
                <div />
                <select
                  value={config.envConns[n.id] ?? n.conn ?? 9}
                  onChange={e => setEnvConn(n.id, Number(e.target.value))}
                  style={{ fontSize: 9.5, padding: "2px 4px", border: "1px solid #e5e7eb",
                    borderRadius: 3, background: "#fafafa", color: "#6b7280" }}>
                  <option value={9}>→ S9 Market Comm</option>
                  <option value={7}>→ S7 Resources</option>
                  <option value={4}>→ S4 Sales / Mktg</option>
                </select>
              </div>
            </div>
          ))}

          {/* Internal nodes */}
          <div style={{ fontSize: 8, color: "#d1d5db", fontFamily: "monospace",
            letterSpacing: 1, textTransform: "uppercase", marginTop: 10, marginBottom: 5 }}>
            Internal
          </div>
          {INTERNAL.map(n => (
            <div key={n.id} style={{ display: "grid", gridTemplateColumns: "36px 1fr",
              alignItems: "center", gap: 5, marginBottom: 4 }}>
              <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
                textAlign: "right" }}>S{n.id}</div>
              <input value={config.nodeLabels[n.id] ?? n.label}
                onChange={e => setNodeLabel(n.id, e.target.value)}
                style={{ ...inputStyle, fontSize: 10, padding: "3px 6px" }} />
            </div>
          ))}
        </div>

        {/* Worlds categories */}
        <div>
          <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
            letterSpacing: 1.5, marginBottom: 8, paddingTop: 5, paddingBottom: 5,
            borderTop: "1px solid #f3f4f6", borderBottom: "1px solid #f3f4f6" }}>
            WORLDS CATEGORIES
            <span style={{ fontSize: 8, fontWeight: 400, color: "#d1d5db", marginLeft: 6 }}>
              respondents select theirs
            </span>
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 3, marginBottom: 8 }}>
            {config.worlds.map((w, i) => (
              <div key={i}
                draggable
                onDragStart={e => handleDragStart(e, i)}
                onDragOver={e => e.preventDefault()}
                onDrop={e => handleDrop(e, i)}
                style={{
                  display: "flex", alignItems: "center", gap: 4,
                  background: dragSrc === i ? "#e0f2e9" : "#fff",
                  border: "1px solid #e5e7eb", borderRadius: 3,
                  padding: "3px 4px", fontSize: 10,
                }}>
                {/* ▲▼ reorder buttons */}
                <div style={{ display: "flex", flexDirection: "column", gap: 0, flexShrink: 0 }}>
                  <button onClick={() => moveWorld(i, -1)} disabled={i === 0}
                    style={{ background: "none", border: "none", cursor: i === 0 ? "default" : "pointer",
                      color: i === 0 ? "#e5e7eb" : "#9ca3af", fontSize: 8, lineHeight: 1,
                      padding: "1px 2px" }}>▲</button>
                  <button onClick={() => moveWorld(i, 1)} disabled={i === config.worlds.length - 1}
                    style={{ background: "none", border: "none",
                      cursor: i === config.worlds.length - 1 ? "default" : "pointer",
                      color: i === config.worlds.length - 1 ? "#e5e7eb" : "#9ca3af",
                      fontSize: 8, lineHeight: 1, padding: "1px 2px" }}>▼</button>
                </div>
                {/* Editable label */}
                <input
                  value={w}
                  onChange={e => editWorld(i, e.target.value)}
                  style={{ flex: 1, fontSize: 10, border: "none", outline: "none",
                    background: "transparent", fontFamily: "system-ui, sans-serif",
                    padding: "2px 2px", minWidth: 0 }}
                />
                {/* Remove */}
                <button onClick={() => removeWorld(w)} style={{
                  background: "none", border: "none", cursor: "pointer",
                  color: "#d1d5db", fontSize: 12, lineHeight: 1, padding: "0 2px",
                  flexShrink: 0,
                }}>×</button>
              </div>
            ))}
          </div>
          <div style={{ display: "flex", gap: 6 }}>
            <input
              value={worldInput}
              onChange={e => setWorldInput(e.target.value)}
              onKeyDown={e => e.key === "Enter" && addWorld()}
              placeholder="Add a World category…"
              style={{ ...inputStyle, flex: 1 }}
            />
            <button onClick={addWorld} style={{
              padding: "4px 10px", fontSize: 11, background: "#2a5c3f",
              color: "#fff", border: "none", borderRadius: 3, cursor: "pointer",
            }}>+</button>
          </div>
        </div>

        {/* Save/Load config */}
        <div style={{ marginTop: 16, paddingTop: 12, borderTop: "1px solid #f3f4f6" }}>
          <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
            letterSpacing: 1.5, marginBottom: 8 }}>SAVE / LOAD CONFIG</div>
          <div style={{ display: "flex", gap: 5 }}>
            <Btn onClick={onSaveJSON}>💾 Save</Btn>
            <Btn onClick={() => fileRef.current.click()}>📂 Load</Btn>
            <Btn onClick={onExportSVG}>⬇ SVG</Btn>
            <Btn onClick={onPrint}>🖨 Print</Btn>
          </div>
          <input ref={fileRef} type="file" accept=".json" onChange={onLoadJSON}
            style={{ display: "none" }} />
        </div>
      </div>

      {/* ── Centre: diagram ── */}
      <DiagramCanvas
        show={show} assess={assess} sel={sel} selEdge={selEdge}
        onSelectNode={handleSelectNode} onSelectEdge={handleSelectEdge}
        enterpriseName={config.enterprise} svgRef={svgRef}
        labelMap={config.nodeLabels}
        envNodes={envNodes} ouNodes={ouNodes}
        envPairs={envPairs} ouPairs={ouPairs}
      />

      {/* ── Right panel: assessment detail + layer toggles + legend ── */}
      <div style={{
        width: 264, background: "#fff", borderLeft: "1.5px solid #e5e7eb",
        display: "flex", flexDirection: "column", overflow: "hidden",
      }}>

        {/* Save/Load/Export — duplicated at top for quick access */}
        <div style={{
          padding: "6px 10px", borderBottom: "1px solid #f3f4f6",
          display: "flex", gap: 4, background: "#fafafa",
        }}>
          <Btn onClick={onSaveJSON}>💾 Save</Btn>
          <Btn onClick={() => fileRef.current.click()}>📂 Load</Btn>
          <Btn onClick={onExportSVG}>⬇ SVG</Btn>
          <Btn onClick={onPrint}>🖨 Print</Btn>
        </div>

        {/* Layer toggles */}
        <div style={{
          padding: "8px 12px", borderBottom: "1px solid #f3f4f6",
          display: "flex", gap: 4, flexWrap: "wrap",
        }}>
          {[
            { k: "int", label: "Internal",    col: C.vsm3  },
            { k: "env", label: "Environment", col: C.env   },
            { k: "ou",  label: "Op Units",    col: C.vsm1  },
          ].map(({ k, label, col }) => (
            <button key={k} onClick={() => setShow(s => ({ ...s, [k]: !s[k] }))} style={{
              padding: "3px 10px", borderRadius: 4, fontSize: 10, cursor: "pointer",
              background: show[k] ? col + "15" : "#f9fafb",
              color:      show[k] ? col : "#9ca3af",
              border:     `1.5px solid ${show[k] ? col : "#e5e7eb"}`,
              fontWeight: 700,
            }}>{label}</button>
          ))}
        </div>

        {/* Assessment detail */}
        <div style={{ padding: "14px 14px 12px", borderBottom: "1px solid #f3f4f6",
          flex: "0 0 auto", overflowY: "auto", maxHeight: "55vh" }}>
          <AssessmentPanel
            sel={sel} selEdge={selEdge}
            assess={assess} setAssess={setAssess}
            notes={notes} setNote={setNote}
            onSelectNode={handleSelectNode}
            setupMode={true}
            labelMap={config.nodeLabels}
            descMap={{ ...config.nodeDescs, ...config.edgeDescs }}
            setDesc={setDesc}
            byId={makeById(envNodes, ouNodes)}
            envPairs={envPairs} ouPairs={ouPairs}
            onSetEnvConn={setEnvConn}
          />
        </div>

        {/* Legend */}
        <div style={{ padding: "12px 14px", flex: 1, overflowY: "auto" }}>
          <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
            letterSpacing: 1.5, marginBottom: 10 }}>VSM TIERS</div>
          {TIERS.map(t => <LR key={t.label} {...t} />)}

          <div style={{ marginTop: 12, borderTop: "1px solid #f3f4f6", paddingTop: 10 }}>
            <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
              letterSpacing: 1.5, marginBottom: 8 }}>ASSESSMENT FILL</div>
            {STATES.filter(s => s.key !== "none").map(s => (
              <div key={s.key} style={{ display: "flex", alignItems: "center", gap: 7, marginBottom: 5 }}>
                <div style={{ width: 14, height: 14, borderRadius: "50%",
                  background: s.fill, border: "1.5px solid #e5e7eb", flexShrink: 0 }} />
                <span style={{ fontSize: 10.5, color: "#374151" }}>{s.label}</span>
              </div>
            ))}
            <div style={{ marginTop: 6, borderTop: "1px solid #f3f4f6", paddingTop: 8 }}>
              <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
                letterSpacing: 1.5, marginBottom: 6 }}>EDGE ASSESSMENT</div>
              {EDGE_STATES.filter(s => s.key !== "none").map(s => (
                <div key={s.key} style={{ display: "flex", alignItems: "center", gap: 7, marginBottom: 5 }}>
                  <div style={{ width: 20, height: 5, borderRadius: 2,
                    background: s.fill, border: "1px solid #e5e7eb", flexShrink: 0 }} />
                  <span style={{ fontSize: 10.5, color: "#374151" }}>{s.label}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════
// ── SURVEY MODE ───────────────────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════════════
function SurveyMode({ config, show, setShow, envNodes = [], ouNodes = [], envPairs = [], ouPairs = [] }) {
  // Per-respondent state (not shared with setup)
  const [respondentName, setRespondentName] = useState("");
  const [selectedWorlds, setSelectedWorlds] = useState([]);
  const [assess, setAssess] = useState({});
  const [notes, setNotes]   = useState({});

  const [sel, setSel]         = useState(null);
  const [selEdge, setSelEdge] = useState(null);
  const [seqIdx, setSeqIdx]   = useState(null);
  const [statusMsg, setStatusMsg] = useState("");

  const surveyFileRef = useRef(null);
  const svgRef = useRef(null);

  const byId = makeById(envNodes, ouNodes);
  const seq = buildAssessmentSequence(show, envNodes, ouNodes, envPairs, ouPairs);
  const total = seq.length;
  const doneCount = seq.filter(item => {
    const k = item.type === "node" ? item.id : item.id;
    return (assess[k] && assess[k] !== "none");
  }).length;
  const progress = total > 0 ? (doneCount / total) * 100 : 0;

  const setNote = (key, field, val) =>
    setNotes(n => ({ ...n, [key]: { ...(n[key] || {}), [field]: val } }));

  const handleSelectNode = node => {
    setSelEdge(null); setSel(node);
    const idx = seq.findIndex(x => x.type === "node" && String(x.id) === String(node.id));
    setSeqIdx(idx >= 0 ? idx : null);
  };

  const handleSelectEdge = edge => {
    setSel(null); setSelEdge(edge);
    const idx = seq.findIndex(x => x.type === "edge" && x.id === edge.key);
    setSeqIdx(idx >= 0 ? idx : null);
  };

  const navTo = idx => {
    if (idx < 0 || idx >= seq.length) return;
    const item = seq[idx];
    setSeqIdx(idx);
    if (item.type === "node") {
      const n = byId(item.id);
      if (n) { setSel(n); setSelEdge(null); }
    } else {
      // edge key format: "a__b"
      const [a, b] = item.id.split("__");
      const aId = isNaN(+a) ? a : +a;
      const bId = isNaN(+b) ? b : +b;
      setSel(null);
      setSelEdge({ key: item.id, a: aId, b: bId, t: "internal" });
    }
  };

  const toggleWorld = w => {
    setSelectedWorlds(prev =>
      prev.includes(w) ? prev.filter(x => x !== w) : [...prev, w]
    );
  };

  const exportJSON = () => {
    const payload = {
      meta: { exportedAt: new Date().toISOString(), tool: "SOFI-VSM" },
      respondent: {
        name: respondentName || "anonymous",
        worlds: selectedWorlds,
      },
      surveyConfig: {
        enterprise: config.enterprise,
        focalPoint: config.focalPoint,
        date: config.date,
        timeFrame: config.timeFrame,
        surveyId: config.surveyId,
      },
      assessments: { nodes: {}, edges: {} },
    };
    // Split assess keys into nodes vs edges
    Object.entries(assess).forEach(([k, v]) => {
      if (k.includes("__")) {
        payload.assessments.edges[k] = { status: v, ...((notes[k]) || {}) };
      } else {
        const nKey = String(k);
        payload.assessments.nodes[nKey] = { status: v, ...((notes[k]) || {}) };
      }
    });
    const ident = (respondentName || "anonymous").replace(/\s+/g, "-").toLowerCase();
    const filename = `sofi-vsm-respondent-${ident}-${Date.now()}.json`;
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }));
    a.download = filename;
    a.click();
    setStatusMsg(`✓ Saved ${filename}`);
    setTimeout(() => setStatusMsg(""), 3500);
  };

  const importJSON = e => {
    const file = e.target.files[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = ev => {
      try {
        const data = JSON.parse(ev.target.result);
        if (data.respondent) {
          setRespondentName(data.respondent.name || "");
          setSelectedWorlds(data.respondent.worlds || []);
        }
        if (data.assessments) {
          const merged = {};
          const mergedNotes = {};
          [...Object.entries(data.assessments.nodes || {}),
           ...Object.entries(data.assessments.edges || {})].forEach(([k, v]) => {
            merged[k] = v.status || "none";
            if (v.evidence || v.suggestions) {
              mergedNotes[k] = { evidence: v.evidence || "", suggestions: v.suggestions || "" };
            }
          });
          setAssess(merged);
          setNotes(mergedNotes);
        }
        setStatusMsg("✓ Response loaded — continue where you left off.");
        setTimeout(() => setStatusMsg(""), 4000);
      } catch {
        setStatusMsg("✗ Could not read file.");
        setTimeout(() => setStatusMsg(""), 4000);
      }
    };
    reader.readAsText(file);
    e.target.value = "";
  };

  const StatusDot = ({ id, isEdge }) => {
    const v = assess[id] || "none";
    const stateList = isEdge ? EDGE_STATES : STATES;
    const fill = stateList.find(s => s.key === v)?.fill ?? "#e5e7eb";
    return (
      <span style={{
        width: 8, height: 8, borderRadius: "50%", background: fill,
        border: "1px solid #e5e7eb", display: "inline-block", flexShrink: 0,
      }} />
    );
  };

  const NavItem = ({ item, active }) => {
    const isEdge = item.type === "edge";
    const handleClick = () => navTo(seq.indexOf(item));
    if (isEdge) {
      const [a, b] = item.id.split("__");
      const aId = isNaN(+a) ? a : +a;
      const bId = isNaN(+b) ? b : +b;
      return (
        <div onClick={handleClick} style={{
          padding: "4px 10px", fontSize: 10, cursor: "pointer",
          display: "flex", justifyContent: "space-between", alignItems: "center",
          borderBottom: "1px solid #f3f4f6",
          background: active ? "#f0fdf4" : "transparent",
          borderLeft: active ? "2px solid #2a5c3f" : "2px solid transparent",
        }}>
          <span style={{ color: "#374151", fontFamily: "monospace", fontSize: 9.5 }}>
            {shortName(aId)}→{shortName(bId)}
          </span>
          <StatusDot id={item.id} isEdge />
        </div>
      );
    }
    const n = byId(item.id);
    return (
      <div onClick={handleClick} style={{
        padding: "5px 10px", fontSize: 11, cursor: "pointer",
        display: "flex", justifyContent: "space-between", alignItems: "center",
        borderBottom: "1px solid #f3f4f6",
        background: active ? "#f0fdf4" : "transparent",
        borderLeft: active ? "2px solid #2a5c3f" : "2px solid transparent",
      }}>
        <span style={{ color: "#374151", fontWeight: 500 }}>
          {n ? n.label.replace("\n", " ") : String(item.id)}
        </span>
        <StatusDot id={item.id} isEdge={false} />
      </div>
    );
  };

  const selEKey = selEdge?.key ?? null;

  return (
    <div style={{ flex: 1, display: "flex", overflow: "hidden" }}>

      {/* ── Left panel ── */}
      <div style={{
        width: 260, background: "#f9fafb", borderRight: "1.5px solid #e5e7eb",
        overflowY: "auto", padding: "12px 12px",
        display: "flex", flexDirection: "column", gap: 0,
      }}>

        {/* Survey identity (read-only) */}
        {(config.enterprise || config.focalPoint) && (
          <div style={{ marginBottom: 14, padding: "10px", background: "#fff",
            border: "1px solid #e5e7eb", borderRadius: 4 }}>
            <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
              letterSpacing: 1.2, marginBottom: 6 }}>SURVEY IDENTITY</div>
            {config.enterprise && (
              <div style={{ fontSize: 11, fontWeight: 700, color: "#111", marginBottom: 3 }}>
                {config.enterprise}
              </div>
            )}
            {config.focalPoint && (
              <div style={{ fontSize: 10, color: "#6b7280", lineHeight: 1.5 }}>
                {config.focalPoint}
              </div>
            )}
            {(config.date || config.timeFrame) && (
              <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace", marginTop: 4 }}>
                {[config.date, config.timeFrame].filter(Boolean).join(" · ")}
              </div>
            )}
            {config.previewText && (
              <div style={{ fontSize: 10, color: "#374151", marginTop: 8,
                paddingTop: 8, borderTop: "1px solid #f3f4f6", lineHeight: 1.55 }}>
                {config.previewText}
              </div>
            )}
          </div>
        )}

        {/* Respondent name */}
        <div style={{ marginBottom: 14 }}>
          <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
            letterSpacing: 1.2, marginBottom: 5 }}>RESPONDENT</div>
          <input
            value={respondentName}
            onChange={e => setRespondentName(e.target.value)}
            placeholder="Your name (optional)"
            style={{
              width: "100%", fontSize: 11, padding: "5px 8px",
              border: "1px solid #e5e7eb", borderRadius: 3,
              fontFamily: "system-ui, sans-serif", boxSizing: "border-box",
            }}
          />
        </div>

        {/* Export / Import */}
        <div style={{ marginBottom: 14 }}>
          <button onClick={exportJSON} style={{
            width: "100%", padding: "7px", fontSize: 10.5, cursor: "pointer",
            background: "#2a5c3f", color: "#fff", border: "none",
            borderRadius: 3, marginBottom: 5, fontWeight: 600,
          }}>⬇ Save / Export My Responses</button>
          <button onClick={() => surveyFileRef.current.click()} style={{
            width: "100%", padding: "6px", fontSize: 10.5, cursor: "pointer",
            background: "#f9fafb", color: "#374151", border: "1px solid #e5e7eb",
            borderRadius: 3,
          }}>⬆ Resume / Import Saved Response</button>
          <input ref={surveyFileRef} type="file" accept=".json" onChange={importJSON}
            style={{ display: "none" }} />
          {statusMsg && (
            <div style={{ fontSize: 9.5, color: "#2a5c3f", fontFamily: "monospace",
              marginTop: 5, textAlign: "center" }}>{statusMsg}</div>
          )}
        </div>

        {/* My Worlds */}
        {config.worlds.length > 0 && (
          <div style={{ marginBottom: 14 }}>
            <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
              letterSpacing: 1.2, marginBottom: 6 }}>MY WORLDS</div>
            <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
              {config.worlds.map(w => (
                <label key={w} style={{
                  display: "flex", alignItems: "center", gap: 8,
                  fontSize: 11, color: "#374151", cursor: "pointer",
                }}>
                  <input
                    type="checkbox"
                    checked={selectedWorlds.includes(w)}
                    onChange={() => toggleWorld(w)}
                    style={{ accentColor: "#2a5c3f", width: 13, height: 13 }}
                  />
                  {w}
                </label>
              ))}
            </div>
          </div>
        )}

        {/* Layer toggles */}
        <div style={{ marginBottom: 14, paddingTop: 10, borderTop: "1px solid #f3f4f6" }}>
          <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
            letterSpacing: 1.2, marginBottom: 6 }}>VISIBLE LAYERS</div>
          <div style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
            {[
              { k: "int", label: "Internal",    col: C.vsm3  },
              { k: "env", label: "Environment", col: C.env   },
              { k: "ou",  label: "Op Units",    col: C.vsm1  },
            ].map(({ k, label, col }) => (
              <button key={k} onClick={() => setShow(s => ({ ...s, [k]: !s[k] }))} style={{
                padding: "2px 8px", borderRadius: 3, fontSize: 10, cursor: "pointer",
                background: show[k] ? col + "15" : "#f9fafb",
                color:      show[k] ? col : "#9ca3af",
                border:     `1.5px solid ${show[k] ? col : "#e5e7eb"}`,
                fontWeight: 700,
              }}>{label}</button>
            ))}
          </div>
        </div>

        {/* Navigate by item */}
        <div style={{ flex: 1 }}>
          <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
            letterSpacing: 1.2, marginBottom: 0, paddingBottom: 5,
            borderBottom: "1px solid #f3f4f6" }}>
            NAVIGATE ({seq.length} items)
          </div>
          {/* Nodes section */}
          <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
            padding: "4px 10px", background: "#f3f4f6", letterSpacing: 1 }}>
            NODES
          </div>
          {seq.filter(x => x.type === "node").map(item => (
            <NavItem key={item.id} item={item}
              active={sel ? String(sel.id) === String(item.id) : false} />
          ))}
          {/* Edges section */}
          <div style={{ fontSize: 9, color: "#9ca3af", fontFamily: "monospace",
            padding: "4px 10px", background: "#f3f4f6", letterSpacing: 1, marginTop: 4 }}>
            EDGES ({seq.filter(x => x.type === "edge").length})
          </div>
          {seq.filter(x => x.type === "edge").map(item => (
            <NavItem key={item.id} item={item}
              active={selEKey === item.id} />
          ))}
        </div>
      </div>

      {/* ── Centre: diagram ── */}
      <DiagramCanvas
        show={show} assess={assess} sel={sel} selEdge={selEdge}
        onSelectNode={handleSelectNode} onSelectEdge={handleSelectEdge}
        enterpriseName={config.enterprise} svgRef={svgRef}
        labelMap={config.nodeLabels || {}}
        envNodes={envNodes} ouNodes={ouNodes}
        envPairs={envPairs} ouPairs={ouPairs}
      />

      {/* ── Right panel: assessment form + prev/next ── */}
      <div style={{
        width: 300, background: "#fff", borderLeft: "1.5px solid #e5e7eb",
        display: "flex", flexDirection: "column", overflow: "hidden",
      }}>

        {/* Assessment form area */}
        <div style={{
          flex: 1, overflowY: "auto", padding: "14px 16px",
        }}>
          {(sel || selEdge) ? (
            <AssessmentPanel
              sel={sel} selEdge={selEdge}
              assess={assess} setAssess={setAssess}
              notes={notes} setNote={setNote}
              onSelectNode={handleSelectNode}
              labelMap={config.nodeLabels || {}}
              descMap={{ ...(config.nodeDescs || {}), ...(config.edgeDescs || {}) }}
              byId={makeById(envNodes, ouNodes)}
              envPairs={envPairs} ouPairs={ouPairs}
            />
          ) : (
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center",
              justifyContent: "center", height: "100%", color: "#9ca3af", textAlign: "center",
              padding: "0 16px" }}>
              <div style={{ fontSize: 32, marginBottom: 12, opacity: 0.4 }}>◎</div>
              <div style={{ fontSize: 11, lineHeight: 1.7 }}>
                Click any node or edge in the diagram to begin your assessment,
                or use the navigation list on the left.
              </div>
            </div>
          )}
        </div>

        {/* Prev / Next navigation */}
        <div style={{
          padding: "10px 14px", borderTop: "1.5px solid #f3f4f6",
          display: "flex", gap: 8, flexShrink: 0,
        }}>
          <button
            disabled={seqIdx === null || seqIdx <= 0}
            onClick={() => navTo((seqIdx ?? 0) - 1)}
            style={{
              flex: 1, padding: "8px", fontSize: 10, cursor: seqIdx === null || seqIdx <= 0 ? "default" : "pointer",
              background: "#f0fdf4", color: "#2a5c3f", border: "1px solid #bbf7d0",
              borderRadius: 3, fontFamily: "monospace", fontWeight: 500,
              opacity: seqIdx === null || seqIdx <= 0 ? 0.35 : 1,
            }}>← Prev</button>
          <button
            disabled={seqIdx === null || seqIdx >= seq.length - 1}
            onClick={() => navTo((seqIdx ?? -1) + 1)}
            style={{
              flex: 1, padding: "8px", fontSize: 10,
              cursor: seqIdx === null || seqIdx >= seq.length - 1 ? "default" : "pointer",
              background: "#2a5c3f", color: "#fff", border: "1px solid #2a5c3f",
              borderRadius: 3, fontFamily: "monospace", fontWeight: 500,
              opacity: seqIdx === null || seqIdx >= seq.length - 1 ? 0.35 : 1,
            }}>Next →</button>
        </div>
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════
// ── ROOT APP ──────────────────────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════════════
export default function SofiVSM() {
  const [mode, setMode] = useState("setup"); // "setup" | "survey"

  // Shared diagram/assessment state (used by Setup)
  const [assess, setAssess] = useState({});
  const [notes, setNotes]   = useState({});
  const [show, setShow]     = useState({ int: true, env: true, ou: true });

  // Config state (set in Setup, read in Survey)
  const [config, setConfig] = useState(() => {
    const nodeLabels = {};
    [...INTERNAL].forEach(n => { nodeLabels[n.id] = n.label; });
    ENV_DEFS.forEach(n => { nodeLabels[n.id] = n.label; });
    OU_DEFS.forEach(n => { nodeLabels[n.id] = n.label; });
    nodeLabels["OUH"]  = "Operating\nUnit Hub";
    nodeLabels["SOUP"] = "Suppliers\n(OU)";
    nodeLabels["COUD"] = "Customers\n(OU)";
    return {
      enterprise: "",
      focalPoint: "",
      previewText: "",
      date: "",
      timeFrame: "",
      surveyId: "",
      worlds: DEFAULT_WORLDS,
      nodeLabels,
      nodeDescs: {},
      edgeDescs: {},
      ouCount: 5,        // starting OU count
      envCount: 9,       // starting ENV count (all 9 named defaults)
      envConns: {},      // { [envId]: internalNodeId } overrides
    };
  });

  const svgRef  = useRef(null);
  const fileRef = useRef(null);

  useEffect(() => {
    const style = document.createElement("style");
    style.textContent = printStyles;
    document.head.appendChild(style);
    return () => document.head.removeChild(style);
  }, []);

  // ── Save/load the whole setup JSON ──────────────────────────────────────
  const saveJSON = () => {
    const data = { version: "sofi-vsm-2.0", config, assess, notes, show };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = "sofi-vsm-facilitator.json";
    a.click();
  };

  const loadJSON = e => {
    const file = e.target.files[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = ev => {
      try {
        const data = JSON.parse(ev.target.result);
        if (data.assess)  setAssess(data.assess);
        if (data.notes)   setNotes(data.notes);
        if (data.show)    setShow(data.show);
        if (data.config)  setConfig(c => ({ ...c, ...data.config }));
      } catch { alert("Could not read file."); }
    };
    reader.readAsText(file);
    e.target.value = "";
  };

  // ── Build a clean, page-fitted SVG string from current diagram state ────
  const buildPrintSVG = () => {
    const svg = svgRef.current; if (!svg) return null;

    // Compute bounding box that wraps all visible content
    // Nodes sit at their absolute x,y with radius 54; zones add some padding
    const R = 54 + 16; // node radius + halo
    const visibleNodes = [
      ...(show.int ? INTERNAL : []),
      ...(show.env ? envNodes : []),
      ...(show.ou  ? ouNodes  : []),
    ];
    if (visibleNodes.length === 0) return null;

    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    visibleNodes.forEach(n => {
      minX = Math.min(minX, n.x - R);
      minY = Math.min(minY, n.y - R);
      maxX = Math.max(maxX, n.x + R);
      maxY = Math.max(maxY, n.y + R);
    });

    // Add padding for zone labels and enterprise name banner
    minX -= 20; minY -= 50; maxX += 20; maxY += 20;
    const vbW = maxX - minX;
    const vbH = maxY - minY;

    // Serialize the inner <g> (the pan/zoom group) and re-wrap it with a
    // clean viewBox so the diagram fills the page exactly, ignoring pan/zoom.
    const innerG = svg.querySelector("g");
    if (!innerG) return null;

    // Clone inner g and reset its transform to just the viewBox origin offset
    const clone = innerG.cloneNode(true);
    clone.setAttribute("transform", `translate(${-minX}, ${-minY})`);

    // Build a fresh SVG with the correct viewBox and print-friendly dimensions
    const ns = "http://www.w3.org/2000/svg";
    const out = document.createElementNS(ns, "svg");
    out.setAttribute("xmlns", ns);
    out.setAttribute("viewBox", `0 0 ${vbW} ${vbH}`);
    out.setAttribute("width",  `${vbW}`);
    out.setAttribute("height", `${vbH}`);

    // Copy defs (markers) from the original
    const defs = svg.querySelector("defs");
    if (defs) out.appendChild(defs.cloneNode(true));

    out.appendChild(clone);
    return new XMLSerializer().serializeToString(out);
  };

  const exportSVG = () => {
    const str = buildPrintSVG(); if (!str) return;
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([str], { type: "image/svg+xml" }));
    a.download = "sofi-vsm.svg";
    a.click();
  };

  const doPrint = () => {
    const str = buildPrintSVG(); if (!str) return;
    // Wrap in a minimal HTML page so the browser print dialog scales to fit
    const html = `<!DOCTYPE html>
<html><head><meta charset="utf-8">
<title>SOFI-VSM</title>
<style>
  @page { size: landscape; margin: 0.5cm; }
  html, body { margin: 0; padding: 0; background: white; }
  svg { width: 100vw; height: 100vh; display: block; }
  @media print { svg { width: 100%; height: auto; } }
</style>
</head><body>${str}
<script>window.onload = () => { window.print(); }<\/script>
</body></html>`;
    const win = window.open("", "_blank");
    if (win) { win.document.write(html); win.document.close(); }
  };

  const setNote = (key, field, val) =>
    setNotes(n => ({ ...n, [key]: { ...(n[key] || {}), [field]: val } }));

  const setNodeLabel = (id, val) =>
    setConfig(c => ({ ...c, nodeLabels: { ...c.nodeLabels, [id]: val } }));

  const setDesc = (key, val) => {
    if (String(key).includes("__")) {
      setConfig(c => ({ ...c, edgeDescs: { ...c.edgeDescs, [key]: val } }));
    } else {
      setConfig(c => ({ ...c, nodeDescs: { ...c.nodeDescs, [key]: val } }));
    }
  };

  const setEnvConn = (id, connVal) =>
    setConfig(c => ({ ...c, envConns: { ...c.envConns, [id]: connVal } }));

  // Compute dynamic nodes and edges from config
  const envNodes = buildENVNodes(config.envCount, config.nodeLabels, config.envConns);
  const ouNodes  = buildOUNodes(config.ouCount, config.nodeLabels);
  const envPairs = buildENVPairs(envNodes);
  const ouPairs  = buildOUPairs(ouNodes);
  const allItems = buildAssessmentSequence(show, envNodes, ouNodes, envPairs, ouPairs);
  const doneCount = allItems.filter(item => {
    const v = assess[item.id];
    return v && v !== "none";
  }).length;
  const progressPct = allItems.length > 0 ? (doneCount / allItems.length) * 100 : 0;

  return (
    <div style={{
      background: "#f8fafc", color: "#111827", height: "100vh",
      display: "flex", flexDirection: "column", overflow: "hidden",
      fontFamily: "system-ui, -apple-system, sans-serif",
    }}>
      {/* ── Header ── */}
      <div style={{
        background: "#1a1a18", borderBottom: "2px solid #2a5c3f",
        padding: "0 16px", display: "flex", alignItems: "center",
        gap: 12, height: 44, flexShrink: 0,
      }}>
        <div style={{ display: "flex", alignItems: "baseline", gap: 10 }}>
          <span style={{ fontSize: 16, fontWeight: 800, letterSpacing: ".04em", color: "#f5f2eb" }}>
            SOFI-VSM
          </span>
          <span style={{ fontSize: 10, color: "#555", fontFamily: "monospace" }}>
            11 spheres · {INT_PAIRS.length} int · {envPairs.length} env · {ouPairs.length} ou
          </span>
        </div>

        {/* Mode tabs */}
        <div style={{ display: "flex", gap: 3, marginLeft: 12 }}>
          {[
            { k: "setup",  label: "⚙ Setup"  },
            { k: "survey", label: "◎ Survey" },
          ].map(({ k, label }) => (
            <button key={k} onClick={() => setMode(k)} style={{
              padding: "4px 14px", fontSize: 10, fontFamily: "monospace",
              fontWeight: 500, letterSpacing: "0.06em", textTransform: "uppercase",
              border: "1px solid #444", borderRadius: 2, cursor: "pointer",
              background: mode === k ? "#2a5c3f" : "transparent",
              color: mode === k ? "#fff" : "#aaa",
              transition: "all 0.15s",
            }}>{label}</button>
          ))}
        </div>

        <div style={{ flex: 1 }} />

        {/* Progress bar (always visible) */}
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <div style={{ width: 120, height: 4, background: "#333", borderRadius: 2 }}>
            <div style={{
              height: 4, background: "#2a5c3f", borderRadius: 2,
              width: `${mode === "setup" ? progressPct : 0}%`,
              transition: "width 0.3s",
            }} />
          </div>
          <span style={{ fontSize: 10, color: "#555", fontFamily: "monospace" }}>
            {mode === "setup" ? `${doneCount} / ${allItems.length}` : "survey mode"}
          </span>
        </div>

        <span style={{ fontSize: 9, color: "#444", fontStyle: "italic" }}>
          © Phillip Cousins, Diane Downs — Sofi Executive Systems LLC
        </span>
      </div>

      {/* ── Body (mode-switched) ── */}
      {mode === "setup" ? (
        <SetupMode
          config={config} setConfig={setConfig}
          assess={assess} setAssess={setAssess}
          notes={notes} setNote={setNote}
          show={show} setShow={setShow}
          svgRef={svgRef}
          onSaveJSON={saveJSON} onLoadJSON={loadJSON}
          onExportSVG={exportSVG} onPrint={doPrint}
          fileRef={fileRef}
          setNodeLabel={setNodeLabel} setDesc={setDesc}
          envNodes={envNodes} ouNodes={ouNodes}
          envPairs={envPairs} ouPairs={ouPairs}
          setEnvConn={setEnvConn}
        />
      ) : (
        <SurveyMode
          config={config}
          show={show} setShow={setShow}
          envNodes={envNodes} ouNodes={ouNodes}
          envPairs={envPairs} ouPairs={ouPairs}
        />
      )}
    </div>
  );
}
